import json
with open('/app/all_products_raw.txt') as f:
    content = f.read()
products = []
try:
    decoder = json.JSONDecoder()
    i = 0
    while i < len(content):
        while i < len(content) and content[i] in ' \t\n\r':
            i += 1
        if i >= len(content):
            break
        if content[i] != '{':
            while i < len(content) and content[i] != '{':
                i += 1
            continue
        try:
            obj, end = decoder.raw_decode(content, i)
            products.append(obj)
            i = end
        except json.JSONDecodeError:
            break
except Exception as e:
    print(f'Error: {e}')
print(f'Found {len(products)} products')
for p in products:
    if 'id' not in p:
