import json, os

all_meta_keys = set()
for i in range(1, 11):
    path = f'/app/prod_{i}.json'
    with open(path) as f:
        content = f.read().strip()
    obj = json.loads(content)
    md = {m['key']: m['value'] for m in obj.get('meta_data', [])}
    all_meta_keys.update(md.keys())
    print(f'Prod {i}: {obj["name"]}')
    for k, v in obj.items():
        if k == 'meta_data':
            for m in v:
                print(f'  meta.{m["key"]} = {m["value"]}')
        elif k != 'meta_data' and isinstance(v, dict) and v:
            print(f'  {k} = {v}')
    print()

print('All unique meta keys:', sorted(all_meta_keys))
